function commandPalette(){const root=$("commandRoot");const actions=[['Dashboard','dashboard'],['Nova faktura','invoice'],['Fakture','invoices'],['Ponude','offers'],['Klijenti','clients'],['Plaćanja','payments'],['Izvještaji','reports'],['Kalendar','calendar'],['Usluge i proizvodi','catalog'],['Ponavljajuće fakture','recurring'],['Izgled fakture','appearance'],['Postavke','settings'],['Import / Export','importexport']];root.innerHTML=`<div class="command-backdrop" id="cmdBack"><div class="command-box"><div class="command-input"><span>⌕</span><input id="cmdInput" placeholder="Šta želite otvoriti?"></div><div class="command-list" id="cmdList"></div></div></div>`;const draw=()=>{const q=$("cmdInput").value.toLowerCase();$("cmdList").innerHTML=actions.filter(a=>a[0].toLowerCase().includes(q)).map(a=>`<button onclick="closeCommand();${a[1]==='importexport'?'openImportExport()':`navigate('${a[1]}')`}"><span>${a[0]}</span><small>Enter</small></button>`).join("")||`<div class="empty">Nema rezultata.</div>`};$("cmdInput").oninput=draw;$("cmdInput").onkeydown=e=>{if(e.key==="Escape")closeCommand();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="s"){e.preventDefault();if((location.hash||"#dashboard")==="#invoice"&&typeof saveInvoiceRecord==="function")saveInvoiceRecord()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="p"&&(location.hash||"")==="#invoice"){e.preventDefault();printCurrentInvoice()};if(e.key==="Enter"){const b=$("cmdList").querySelector("button");if(b)b.click()}};$("cmdBack").onclick=e=>{if(e.target.id==="cmdBack")closeCommand()};draw();$("cmdInput").focus()}
function closeCommand(){$("commandRoot").innerHTML=""}
function initSearch(){window.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();commandPalette()}if(e.key==="Escape"){closeCommand();closeModal();closeProfileMenu?.()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="s"){e.preventDefault();if((location.hash||"#dashboard")==="#invoice"&&typeof saveInvoiceRecord==="function")saveInvoiceRecord()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="p"&&(location.hash||"")==="#invoice"){e.preventDefault();printCurrentInvoice()}})}
