function topSearchResults(q){const needle=q.trim().toLowerCase();if(!needle)return[];const invoices=getInvoices().filter(x=>String(`${x.number} ${x.clientName||""} ${x.clientEmail||""}`).toLowerCase().includes(needle)).slice(0,4).map(x=>({type:"invoice",id:x.id,title:x.number,detail:`${x.clientName||"Bez klijenta"} · ${money(x.total,x.currency)}`}));const clients=getClients().filter(x=>String(`${x.name||""} ${x.email||""} ${x.city||""}`).toLowerCase().includes(needle)).slice(0,4).map(x=>({type:"client",id:x.name||"",title:x.name||"Bez naziva",detail:x.email||x.city||"Klijent"}));const offers=getOffers().filter(x=>String(`${x.number||""} ${x.clientName||""}`).toLowerCase().includes(needle)).slice(0,3).map(x=>({type:"offer",id:x.id,title:x.number||"Ponuda",detail:x.clientName||"Ponuda"}));const catalog=getCatalog().filter(x=>String(`${x.name||""} ${x.description||""} ${x.category||""}`).toLowerCase().includes(needle)).slice(0,3).map(x=>({type:"catalog",id:x.code||x.name||"",title:x.name||"Stavka kataloga",detail:x.category||x.type||"Katalog"}));const pages=[['dashboard','Dashboard'],['invoice','Nova faktura'],['invoices','Fakture'],['offers','Ponude'],['clients','Klijenti'],['payments','Plaćanja'],['calendar','Kalendar'],['catalog','Usluge i proizvodi'],['settings','Postavke'],['importexport','Import / Export']].filter(x=>x[1].toLowerCase().includes(needle)).map(x=>({type:"page",id:x[0],title:x[1],detail:"Otvori stranicu"}));return [...invoices,...clients,...offers,...catalog,...pages].slice(0,8)}
function closeTopbarSearch(){const root=$("commandRoot");if(root?.querySelector("#topSearchBack"))root.innerHTML=""}
function pulseSearchTarget(selector,needle=''){setTimeout(()=>{const match=[...document.querySelectorAll('table tbody tr')].find(row=>row.textContent.toLowerCase().includes(needle.toLowerCase()));const target=document.querySelector(selector)||match||document.querySelector("#viewContainer .page-heading");if(!target)return;target.scrollIntoView({behavior:"smooth",block:"center"});target.classList.remove("search-target-pulse");void target.offsetWidth;target.classList.add("search-target-pulse");setTimeout(()=>target.classList.remove("search-target-pulse"),1800)},80)}
function openTopSearchResult(type,id){const search=$("globalSearch"),query=search?.value||"";closeTopbarSearch();if(search)search.value="";if(type==="invoice"){navigate("invoices");setTimeout(()=>{const filter=$("invoiceFilter");if(filter){filter.value=query;filter.dispatchEvent(new Event("input"));pulseSearchTarget(`[data-search-invoice="${CSS.escape(String(id))}"]`,query)}},0)}else if(type==="client"){navigate("clients");setTimeout(()=>{const filter=$("clientFilter");if(filter){filter.value=query;filter.dispatchEvent(new Event("input"));pulseSearchTarget(`[data-search-client="${CSS.escape(String(id))}"]`,query)}},0)}else if(type==="offer"){navigate("offers");setTimeout(()=>{const filter=$("offerFilter");if(filter){filter.value=query;filter.dispatchEvent(new Event("input"));pulseSearchTarget(`[data-search-offer="${CSS.escape(String(id))}"]`,query)}},0)}else if(type==="catalog"){navigate("catalog");pulseSearchTarget(`[data-search-catalog="${CSS.escape(String(id))}"]`,query)}else{navigate(id);pulseSearchTarget("#viewContainer .page-heading")}}
function initTopSearchExperience(){const input=$("globalSearch"),host=input?.closest(".topbar-search");if(!input||!host)return;const draw=()=>{const rows=topSearchResults(input.value);$("topSearchResults")?.remove();if(!input.value.trim())return;const list=document.createElement("div");list.id="topSearchResults";list.className="top-search-results";list.innerHTML=rows.length?rows.map(x=>`<button type="button" onclick="openTopSearchResult('${x.type}','${esc(x.id)}')"><span class="search-result-type">${({invoice:"Faktura",client:"Klijent",offer:"Ponuda",catalog:"Katalog",page:"Stranica"})[x.type]}</span><span><strong>${esc(x.title)}</strong><small>${esc(x.detail)}</small></span></button>`).join(""):'<div class="search-empty">Nema rezultata za ovaj unos.</div>';host.appendChild(list)};input.oninput=draw;input.onkeydown=e=>{if(e.key==="Escape"){input.value="";$("topSearchResults")?.remove();input.blur()}if(e.key==="Enter"){const first=topSearchResults(input.value)[0];if(first)openTopSearchResult(first.type,first.id)}};document.addEventListener("click",e=>{if(!host.contains(e.target))$("topSearchResults")?.remove()})}
initTopSearchExperience();
function migrateLegacyCurrencies(){let changed=false;const convert=x=>{if(x&&x.currency==="KM"){x.currency="BAM";changed=true}return x};const settings=getSettings();if(settings.currency==="KM"){settings.currency="BAM";saveSettings(settings);changed=true}const invoices=getInvoices().map(convert),offers=getOffers().map(convert),catalog=getCatalog().map(convert);if(changed){saveInvoices(invoices);saveOffers(offers);saveCatalog(catalog);refreshCurrentView()}}
