const recordPaymentModalBase=recordPaymentModal;recordPaymentModal=function(id){recordPaymentModalBase(id);const invoice=getInvoices().find(x=>String(x.id)===String(id));if(!invoice?.milestones?.length)return;invoice.milestones.forEach((m,i)=>{if(!m.id)m.id=`milestone_${id}_${i}`});const select=`<div class="field"><label>Pripadajuća rata</label><select id="payMilestone"><option value="">Automatski rasporedi po ratama</option>${invoice.milestones.map(m=>`<option value="${esc(m.id)}">${esc(m.name||"Rata")} · ${money(m.amount,invoice.currency)}</option>`).join("")}</select></div>`;$('payNote')?.closest('.grid-2')?.insertAdjacentHTML('beforeend',select)};
const savePaymentBase=savePayment;savePayment=function(id){const selected=$('payMilestone')?.value||"",amount=Math.max(0,+$('payAmount')?.value||0),before=(getInvoices().find(x=>String(x.id)===String(id))?.payments||[]).length;savePaymentBase(id);const rows=getInvoices(),invoice=rows.find(x=>String(x.id)===String(id));if(!invoice?.milestones?.length||(invoice.payments||[]).length<=before)return;invoice.milestones.forEach((m,i)=>{if(!m.id)m.id=`milestone_${id}_${i}`;m.paidAmount=Math.max(0,+m.paidAmount||0)});let remaining=amount,targets=selected?[invoice.milestones.find(m=>m.id===selected)].filter(Boolean):invoice.milestones;for(const milestone of targets){if(remaining<=0)break;const available=Math.max(0,(+milestone.amount||0)-(+milestone.paidAmount||0)),used=Math.min(available,remaining);milestone.paidAmount=(+milestone.paidAmount||0)+used;remaining-=used;milestone.status=milestone.paidAmount>=+milestone.amount&&+milestone.amount>0?"paid":"pending"}const payment=invoice.payments[invoice.payments.length-1];payment.milestoneId=selected||null;saveInvoices(rows);refreshCurrentView()};
function openCreateMenu(){const actions=[['Faktura','Kreiraj novu fakturu','navigate(\'invoice\')'],['Ponuda','Pripremi novu ponudu','renderOfferEditor()'],['Klijent','Dodaj novog klijenta','clientModal()'],['Usluga ili proizvod','Dodaj stavku u katalog','catalogModal()'],['Trošak','Evidentiraj poslovni trošak','addExpense()'],['Projekat','Kreiraj projekat','addProject()'],['Zadatak','Dodaj interni zadatak','addTask()']];openModal('Kreiraj',`<div class="create-menu">${actions.map(a=>`<button onclick="closeModal();${a[2]}"><strong>${a[0]}</strong><small>${a[1]}</small><span>→</span></button>`).join("")}</div>`) }
