const topSearchResultsWithWorkspace=topSearchResults;topSearchResults=function(query){const rows=topSearchResultsWithWorkspace(query),needle=query.trim().toLowerCase();if(!needle)return rows;const workspace=[['expenses','Troškovi','Pregled i evidencija poslovnih troškova'],['projects','Projekti','Projekti, budžeti i povezane stavke'],['tasks','Zadaci','Interni zadaci i rokovi']].filter(item=>item[1].toLowerCase().includes(needle)).map(item=>({type:'page',id:item[0],title:item[1],detail:item[2]}));return[...rows,...workspace].slice(0,8)};
commandPalette=function(){const actions=[['Dashboard','dashboard'],['Nova faktura','invoice'],['Fakture','invoices'],['Ponude','offers'],['Klijenti','clients'],['Plaćanja','payments'],['Izvještaji','reports'],['Kalendar','calendar'],['Usluge i proizvodi','catalog'],['Troškovi','expenses'],['Projekti','projects'],['Zadaci','tasks'],['Ponavljajuće fakture','recurring'],['Postavke','settings'],['Import / Export','importexport']];const root=$('commandRoot');root.innerHTML=`<div class="command-backdrop" id="cmdBack"><div class="command-box"><button class="icon-close command-close" onclick="closeCommand()" aria-label="Zatvori">×</button><div class="command-input"><span>⌕</span><input id="cmdInput" placeholder="Šta želite otvoriti?"></div><div class="command-list" id="cmdList"></div></div></div>`;const draw=()=>{const query=$('cmdInput').value.toLowerCase();$('cmdList').innerHTML=actions.filter(action=>action[0].toLowerCase().includes(query)).map(action=>`<button onclick="closeCommand();navigate('${action[1]}')"><span>${action[0]}</span><small>Enter</small></button>`).join('')||'<div class="empty">Nema rezultata.</div>'};$('cmdInput').oninput=draw;$('cmdInput').onkeydown=event=>{if(event.key==='Escape')closeCommand();if(event.key==='Enter')$('cmdList').querySelector('button')?.click()};$('cmdBack').onclick=event=>{if(event.target.id==='cmdBack')closeCommand()};draw();$('cmdInput').focus()};
function openTopbarSearchOverlay(initialValue=''){const root=$('commandRoot');if(!root)return;root.innerHTML=`<div class="command-backdrop top-search-backdrop" id="topSearchBack"><div class="command-box top-search-box" role="dialog" aria-modal="true" aria-label="Pretraga"><button class="icon-close command-close" onclick="closeTopbarSearch()" aria-label="Zatvori">×</button><div class="command-input"><span>⌕</span><input id="topSearchInput" placeholder="Pretraži fakture, klijente, ponude i katalog..." autocomplete="off"></div><p class="top-search-help">Izaberite rezultat za odlazak direktno na zapis.</p><div class="command-list" id="topSearchList"></div></div></div>`;const overlayInput=$('topSearchInput'),topInput=$('globalSearch');const draw=()=>{const query=overlayInput.value.trim(),rows=topSearchResults(query);if(topInput)topInput.value=query;$('topSearchList').innerHTML=!query?'<div class="empty">Počnite unositi broj fakture, ime klijenta, ponudu ili stranicu.</div>':rows.length?rows.map(row=>`<button type="button" onclick="openTopSearchResult('${row.type}','${esc(row.id)}')"><span class="search-result-type">${({invoice:'Faktura',client:'Klijent',offer:'Ponuda',catalog:'Katalog',page:'Stranica'})[row.type]||'Rezultat'}</span><span><strong>${esc(row.title)}</strong><small>${esc(row.detail)}</small></span></button>`).join(''):'<div class="empty">Nema rezultata za ovaj unos.</div>'};overlayInput.value=initialValue;overlayInput.oninput=draw;overlayInput.onkeydown=event=>{if(event.key==='Escape'){if(topInput)topInput.value='';closeTopbarSearch()}if(event.key==='Enter')$('topSearchList')?.querySelector('button')?.click()};draw();overlayInput.focus()}
function bindTopbarSearch(){const existing=$('globalSearch');if(!existing)return;const input=existing.cloneNode(true);existing.replaceWith(input);input.onfocus=()=>openTopbarSearchOverlay(input.value);input.onkeydown=event=>{if(event.key==='Escape'){input.value='';input.blur();closeTopbarSearch()}if(event.key==='Enter'){event.preventDefault();openTopbarSearchOverlay(input.value)}}}
