/* Centralne UX ispravke: bez browser dijaloga, konzistentne valute i obavijesti. */
function migrateRemovedCurrency(){const convert=row=>row&&row.currency==='HRK'?{...row,currency:'EUR'}:row,settings=getSettings?.();if(settings?.currency==='HRK')saveSettings({...settings,currency:'EUR'});[[getInvoices,saveInvoices],[getOffers,saveOffers],[getCatalog,saveCatalog]].forEach(([read,save])=>{const rows=read(),next=rows.map(convert);if(rows.some((row,i)=>row!==next[i]))save(next)});document.querySelectorAll('select option[value="HRK"]').forEach(option=>option.remove())}
function migrateDemoCompanyName(){const profile=currentProfile?.(),company=getCompany?.();if(profile?.id!=='demo')return;if(company?.name==='Northline Studio d.o.o.'||!company?.country){saveCompany({...company,name:company.name==='Northline Studio d.o.o.'?'Faktura d.o.o.':company.name,country:company.country||'Bosna i Hercegovina',email:company.name==='Northline Studio d.o.o.'?'office@faktura.example':company.email,web:company.name==='Northline Studio d.o.o.'?'faktura.example':company.web});updateCompanyChrome?.()}const clients=getClients(),nextClients=clients.map(client=>client.country?client:{...client,country:'Bosna i Hercegovina'});if(nextClients.some((client,index)=>client!==clients[index]))saveClients(nextClients);const invoices=getInvoices(),nextInvoices=invoices.map(invoice=>invoice.clientCountry?invoice:{...invoice,clientCountry:nextClients.find(client=>client.name===invoice.clientName)?.country||'Bosna i Hercegovina'});if(nextInvoices.some((invoice,index)=>invoice!==invoices[index]))saveInvoices(nextInvoices);const offers=getOffers(),nextOffers=offers.map(offer=>offer.clientCountry?offer:{...offer,clientCountry:nextClients.find(client=>client.name===offer.clientName)?.country||'Bosna i Hercegovina'});if(nextOffers.some((offer,index)=>offer!==offers[index]))saveOffers(nextOffers)}
const switchProfileBaseWithDemoMigration=switchProfile;
