function clearNotifications(){const ids=getNotifications().map(item=>String(item.id)),dismissed=new Set(fsGet('v12_dismissed_notifications',[]));ids.forEach(id=>dismissed.add(id));fsSet('v12_dismissed_notifications',[...dismissed]);closeNotifications();updateNotifications?.();toast('Obavijesti su očišćene.')}
function openNotifications(){const host=$('notificationPopover');if(!host)return;if(host.innerHTML){closeNotifications();return}const items=getNotifications?.()||[];host.innerHTML=`<div class="notification-popover"><div class="notification-popover-head"><strong>Obavijesti</strong><button class="btn light tiny" onclick="clearNotifications()">Očisti obavijesti</button></div>${items.length?items.map(item=>`<button class="notification-row" onclick="closeNotifications();editInvoice(${item.id})"><strong>${esc(item.title)}</strong><small>${esc(item.detail)}</small></button>`).join(''):'<div class="empty">Nema novih obavijesti.</div>'}</div>`}
