function confirmDestructive(title,details,yes){openModal(title,`<div class="danger-profile-copy"><strong>${esc(details)}</strong><p>Ova radnja je trajna i nije je moguće opozvati.</p></div>`,`<div class="modal-actions"><button class="btn light" onclick="closeModal()">Odustani</button><button class="btn danger" id="confirmDestructive">Potvrdi brisanje</button></div>`);$('confirmDestructive').onclick=()=>{closeModal();yes()}}
removeClient=function(index){const client=getClients()[index];if(!client)return;confirmDestructive('Obrisati klijenta?',`Brišete klijenta „${client.name||'bez naziva'}“. Postojeće fakture ostaju sačuvane, ali klijent više neće biti dostupan za nove dokumente.`,()=>{const clients=getClients();clients.splice(index,1);saveClients(clients);renderClients();toast('Klijent je obrisan.')})};
removeCatalog=function(index){const item=getCatalog()[index];if(!item)return;confirmDestructive('Obrisati stavku kataloga?',`Brišete stavku „${item.name||item.code||'bez naziva'}“. Postojeći dokumenti ostaju nepromijenjeni.`,()=>{const rows=getCatalog();rows.splice(index,1);saveCatalog(rows);renderCatalog();toast('Stavka je obrisana.')})};
deleteExpense=function(index){const expense=extGet('expenses')[index];if(!expense)return;confirmDestructive('Obrisati trošak?',`Brišete trošak „${expense.name||'bez opisa'}“ u iznosu ${moneyValue(expense.amount,expense.currency||getSettings().currency)}.`,()=>{const rows=extGet('expenses');rows.splice(index,1);extSet('expenses',rows);renderExpenses();toast('Trošak je obrisan.')})};
deleteTask=function(index){const task=extGet('tasks')[index];if(!task)return;confirmDestructive('Obrisati zadatak?',`Brišete zadatak „${task.name||'bez naziva'}“${task.due?` s rokom ${formatDate(task.due)}`:''}.`,()=>{const rows=extGet('tasks');rows.splice(index,1);extSet('tasks',rows);renderTasks();toast('Zadatak je obrisan.')})};
deleteProject=function(index){const project=extGet('projects')[index];if(!project)return;confirmDestructive('Obrisati projekat?',`Brišete projekat „${project.name||'bez naziva'}“. Povezani troškovi, zadaci i fakture ostaju sačuvani, ali gube ovaj pregled projekta.`,()=>{const rows=extGet('projects');rows.splice(index,1);extSet('projects',rows);closeModal();renderProjects();toast('Projekat je obrisan.')})};
deleteDocumentRecord=function(index){const documentRecord=extGet('documents')[index];if(!documentRecord)return;confirmDestructive('Obrisati evidenciju dokumenta?',`Brišete evidenciju „${documentRecord.name||documentRecord.file||'bez naziva'}“${documentRecord.file?` za datoteku ${documentRecord.file}`:''}. Originalna datoteka na računaru neće biti obrisana.`,()=>{const rows=extGet('documents');rows.splice(index,1);extSet('documents',rows);renderDocuments();toast('Evidencija priloga je obrisana.')})};
deleteProfile=function(id){const profiles=profileMeta();const profile=profiles.find(item=>item.id===id);if(!profile)return;if(isDemoProfile(profile)){toast('Demo profil se ne može obrisati. Možete ga resetovati u Postavkama.');return}if(profiles.length<=1){toast('Mora postojati najmanje jedan profil.');return}confirmDestructive('Obrisati profil firme?',`Brišete profil „${profile.name}“ i sve njegove lokalne klijente, fakture, ponude, postavke i priloge.`,()=>{clearProfileWorkspace(id);const next=profiles.filter(item=>item.id!==id);saveProfileMeta(next);if(activeProfileId()===id)setActiveProfileId(next[0].id);closeProfileMenu();updateCompanyChrome();refreshCurrentView();toast('Profil je obrisan.')})};
newInvoice=function(){confirmAction('Kreirati novu fakturu? Trenutni nespremljeni nacrt bit će zamijenjen.',()=>{saveDraft(null);renderInvoice()})};
deleteOffer=function(id){const offer=getOffers().find(item=>item.id===id);if(!offer)return;confirmDestructive('Obrisati ponudu?',`Brišete ponudu „${offer.number||'bez broja'}“ za klijenta ${offer.clientName||'bez klijenta'}.`,()=>{saveOffers(getOffers().filter(item=>item.id!==id));renderOffers();toast('Ponuda je obrisana.')})};
runInvoiceBulk=function(action){const ids=[...document.querySelectorAll('.bulk-invoice:checked')].map(item=>String(item.value));if(!ids.length){toast('Označite barem jednu fakturu.');return}const apply=()=>{const rows=getInvoices().filter(item=>action!=='delete'||!ids.includes(String(item.id))).map(item=>ids.includes(String(item.id))&&action!=='delete'?{...item,status:action,paidAmount:action==='paid'?(+item.total||0):item.paidAmount,updatedAt:Date.now()}:item);saveInvoices(rows);closeModal();renderHistory();updateInvoiceBadge();toast(action==='delete'?'Odabrane fakture su obrisane.':'Status odabranih faktura je ažuriran.')};if(action==='delete'){const names=getInvoices().filter(item=>ids.includes(String(item.id))).map(item=>item.number).join(', ');confirmDestructive('Obrisati fakture?',`Brišete ${ids.length} faktura: ${names}.`,apply)}else apply()};
runEntityBulk=function(type,action){const ids=[...document.querySelectorAll('.bulk-entity:checked')].map(item=>+item.value);if(!ids.length){toast('Označite barem jednu stavku.');return}const config={clients:[getClients,saveClients],offers:[getOffers,saveOffers],catalog:[getCatalog,saveCatalog]}[type];if(!config)return;const apply=()=>{let rows=config[0]();rows=action==='delete'?rows.filter((_,index)=>!ids.includes(index)):rows.map((item,index)=>ids.includes(index)?{...item,...(type==='catalog'?{active:action==='active'}:{status:action})}:item);config[1](rows);closeModal();refreshCurrentView();toast('Masovna radnja je izvršena.')};if(action==='delete'){const names=ids.map(index=>config[0]()[index]).filter(Boolean).map(item=>item.name||item.number||'stavka').join(', ');confirmDestructive('Obrisati odabrane stavke?',`Brišete: ${names}.`,apply)}else apply()};
runWorkspaceBulk=function(type,action='delete'){const key={expenses:'expenses',projects:'projects',tasks:'tasks',documents:'documents'}[type],ids=[...document.querySelectorAll('.bulk-workspace:checked')].map(item=>+item.value);if(!key||!ids.length){toast('Označite barem jednu stavku.');return}const apply=()=>{let rows=extGet(key);if(action==='delete')rows=rows.filter((_,index)=>!ids.includes(index));else if(type==='tasks')rows=rows.map((item,index)=>ids.includes(index)?{...item,done:action==='done'}:item);else if(type==='expenses')rows=rows.map((item,index)=>ids.includes(index)?{...item,category:$('bulkWorkspaceValue').value.trim()}:item);else if(type==='documents')rows=rows.map((item,index)=>ids.includes(index)?{...item,type:$('bulkWorkspaceValue').value}:item);extSet(key,rows);closeModal();refreshCurrentView();toast(action==='delete'?'Odabrane stavke su obrisane.':'Odabrane stavke su ažurirane.')};if(action==='delete'){const names=ids.map(index=>extGet(key)[index]).filter(Boolean).map(item=>item.name||'stavka').join(', ');confirmDestructive('Obrisati odabrane stavke?',`Brišete: ${names}.`,apply)}else apply()};
setTimeout(()=>{migrateRemovedCurrency();migrateDemoCompanyName();updateNotifications?.()},0);

/* Dopune urednika fakture bez mijenjanja postojećeg A4 renderer-a. */
const renderInvoiceBaseWithCountry=renderInvoice;
renderInvoice=function(data=null){renderInvoiceBaseWithCountry(data);const itemsHead=$('itemsBody')?.closest('table')?.querySelector('thead tr');if(itemsHead)itemsHead.innerHTML='<th></th><th style="width:31%">Naziv i opis stavke</th><th>Količina</th><th>Cijena</th><th>Popust</th><th>PDV</th><th>Ukupno</th><th></th>';const city=$('clientCity')?.closest('.field');if(city&&!$('clientCountry')){city.insertAdjacentHTML('afterend','<div class="field"><label>Država</label><input id="clientCountry" value="'+esc(invoiceState.clientCountry||'')+'"></div>');$('clientCountry').addEventListener('input',()=>{invoiceState.clientCountry=$('clientCountry').value;persistInvoice()})}};
const selectClientBaseWithCountry=selectClient;
selectClient=function(index){selectClientBaseWithCountry(index);const client=getClients()[index];if(client){invoiceState.clientCountry=client.country||'';if($('clientCountry'))$('clientCountry').value=invoiceState.clientCountry;persistInvoice()}};
const clearClientBaseWithCountry=clearClient;
clearClient=function(){clearClientBaseWithCountry();invoiceState.clientCountry='';if($('clientCountry'))$('clientCountry').value=''};
renderItems=function(){const body=$('itemsBody');if(!body)return;body.innerHTML=invoiceState.items.map((item,index)=>`<tr data-row="${index}"><td class="item-drag"><button type="button" class="item-drag-handle" draggable="true" aria-label="Promijeni redoslijed stavke" title="Povucite za promjenu redoslijeda">⠿</button></td><td><input data-item="${index}" data-k="description" value="${esc(item.description)}" placeholder="Naziv stavke"><input class="item-description" data-item="${index}" data-k="itemDescription" value="${esc(item.itemDescription||'')}" placeholder="Opis stavke"></td><td><input class="num" type="number" min="0" step="0.01" data-item="${index}" data-k="qty" value="${item.qty}"></td><td><input class="num" type="number" min="0" step="0.01" data-item="${index}" data-k="price" value="${item.price}"></td><td><input class="num" type="number" min="0" step="0.01" data-item="${index}" data-k="discount" value="${item.discount}"></td><td><input class="num" type="number" min="0" step="0.01" data-item="${index}" data-k="vat" value="${item.vat}"></td><td id="itemTotal${index}"><strong>${money((+item.qty||0)*(+item.price||0)*(1-(+item.discount||0)/100)*(1+(+item.vat||0)/100),invoiceState.currency)}</strong></td><td><button class="remove-item" onclick="removeInvoiceItem(${index})">×</button></td></tr>`).join('');body.querySelectorAll('[data-item]').forEach(element=>element.addEventListener('input',event=>{const index=+event.target.dataset.item,key=event.target.dataset.k,item=invoiceState.items[index];item[key]=['description','itemDescription'].includes(key)?event.target.value:+event.target.value||0;saveDraft(JSON.parse(JSON.stringify(invoiceState)));updateItemTotal(index);updatePreview()}));let drag=null;body.querySelectorAll('.item-drag-handle').forEach(handle=>{const row=handle.closest('tr');handle.ondragstart=event=>{drag=+row.dataset.row;row.classList.add('dragging');event.dataTransfer.effectAllowed='move'};handle.ondragend=()=>{row.classList.remove('dragging');drag=null}});body.querySelectorAll('tr[data-row]').forEach(row=>{row.ondragover=event=>{event.preventDefault();event.dataTransfer.dropEffect='move'};row.ondrop=event=>{event.preventDefault();const target=+row.dataset.row;if(drag===null||drag===target)return;const [moved]=invoiceState.items.splice(drag,1);invoiceState.items.splice(target,0,moved);persistInvoice();renderItems()}});renderMilestones()};
function moveInvoiceItem(from,to){if(from===to||from<0||to<0||from>=invoiceState.items.length||to>=invoiceState.items.length)return false;const [moved]=invoiceState.items.splice(from,1);invoiceState.items.splice(to,0,moved);persistInvoice();renderItems();setTimeout(()=>document.querySelector(`tr[data-row="${to}"] .item-drag-handle`)?.focus(),0);return true}
document.addEventListener('keydown',event=>{const handle=event.target.closest?.('.item-drag-handle');if(!handle||!['ArrowUp','ArrowDown'].includes(event.key))return;const from=+handle.closest('tr')?.dataset.row,to=event.key==='ArrowUp'?from-1:from+1;if(moveInvoiceItem(from,to))event.preventDefault()});
addCatalogToInvoice=function(){const rows=getCatalog?.()||[];if(!rows.length){toast('Katalog je prazan. Prvo dodajte stavku u Katalog.');return}openModal('Dodaj iz kataloga',`<div class="catalog-picker"><div class="catalog-picker-head"><span>Naziv</span><span>Kategorija</span><span>Cijena</span><span>PDV</span></div>${rows.map((item,index)=>`<button class="catalog-picker-row" onclick="chooseCatalogItem(${index})"><strong>${esc(item.name)}</strong><span>${esc(item.category||item.type||'—')}</span><span>${money(item.price,item.currency)}</span><span>${item.vat||0}%</span></button>`).join('')}</div>`)};
chooseCatalogItem=function(index){const item=getCatalog()[index];if(!item)return;invoiceState.items.push({description:item.name||'',itemDescription:item.description||'',qty:1,price:+item.price||0,discount:+item.discount||0,vat:+item.vat||0});saveDraft(invoiceState);closeModal();renderItems();updatePreview();toast('Stavka je dodana u fakturu.')};
renderClientOptions=function(){const box=$('clientOptions');if(!box)return;const query=($('clientPickerSearch')?.value||'').trim().toLowerCase(),rows=getClients().map((client,index)=>({client,index})).filter(({client})=>`${client.name||''} ${client.email||''} ${client.city||''} ${client.country||''}`.toLowerCase().includes(query));box.innerHTML=rows.length?`<div class="invoice-client-picker-head"><span>Klijent</span><span>Kontakt</span><span>Lokacija</span></div>${rows.map(({client,index})=>{const color=clientAvatarColor(client),avatar=client.logo?`<span class="client-option-avatar client-logo-avatar"><img src="${esc(client.logo)}" alt=""></span>`:`<span class="client-option-avatar" style="background:${esc(color)};color:${clientAvatarText(color)}">${esc(initials(client.name||'K'))}</span>`;return`<button class="client-option invoice-client-option" onclick="selectClient(${index})">${avatar}<strong>${esc(client.name||'Bez naziva')}</strong><span>${esc(client.email||client.phone||'—')}</span><span>${esc([client.city,client.country].filter(Boolean).join(', ')||'—')}</span></button>`}).join('')}`:'<div class="empty" style="padding:24px 12px">Nema klijenata.</div>'};
const updatePreviewBaseWithItemDescription=updatePreview;
updatePreview=function(){updatePreviewBaseWithItemDescription();const clientParty=document.querySelector('#a4Preview .sample-parties>div:last-child');if(clientParty&&invoiceState.clientCountry&&!clientParty.querySelector('.invoice-client-country'))clientParty.insertAdjacentHTML('beforeend',`<span class="invoice-client-country">${esc(invoiceState.clientCountry)}</span>`);document.querySelectorAll('#a4Preview tbody tr').forEach((row,index)=>{const detail=invoiceState.items[index]?.itemDescription;if(detail){const cell=row.querySelector('td');if(cell&&!cell.querySelector('small'))cell.insertAdjacentHTML('beforeend',`<small style="display:block;color:#77808d;margin-top:2px">${esc(detail)}</small>`)}})};

/* Klijenti: logo se optimizira prije lokalnog spremanja i koristi kao oznaka svuda. */
let clientLogoDraft='';
const clientAvatarBaseWithLogo=clientAvatar;
clientAvatar=function(client){return client?.logo?`<span class="client-avatar client-logo-avatar" style="background:${esc(clientAvatarColor(client))}"><img src="${esc(client.logo)}" alt=""></span>`:clientAvatarBaseWithLogo(client)};
const clientModalBaseWithLogo=clientModal;
clientModal=function(index=null){clientModalBaseWithLogo(index);const client=index===null?{}:getClients()[index]||{};clientLogoDraft=client.logo||'';const color=$('cmAvatarColor')?.closest('.avatar-color-field');if(!color)return;const preview=clientLogoDraft?`<img src="${esc(clientLogoDraft)}" alt="Logo klijenta">`:`<span>${esc(initials(client.name||'K'))}</span>`;color.insertAdjacentHTML('afterend',`<div class="field client-logo-field"><label>Logo klijenta</label><div class="client-logo-upload"><div class="client-logo-preview" id="clientLogoPreview">${preview}</div><div><label class="btn light client-logo-button" for="cmLogoFile">↑ Odaberi logo</label><input id="cmLogoFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><small>PNG, JPG, WEBP ili GIF · lokalno se optimizira na 64 × 64 px.</small></div></div></div>`);$('cmLogoFile').onchange=event=>{const file=event.target.files?.[0];if(file)resizeClientLogo(file)}};
function resizeClientLogo(file){if(!file.type.startsWith('image/')){toast('Odaberite podržanu slikovnu datoteku.');return}const reader=new FileReader();reader.onload=event=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,64,64);const scale=Math.max(64/image.width,64/image.height),width=image.width*scale,height=image.height*scale;ctx.drawImage(image,(64-width)/2,(64-height)/2,width,height);clientLogoDraft=canvas.toDataURL('image/png');const preview=$('clientLogoPreview');if(preview)preview.innerHTML=`<img src="${esc(clientLogoDraft)}" width="64" height="64" alt="Logo klijenta">`;toast('Logo je optimiziran na 64 × 64 px.')} ;image.onerror=()=>toast('Sliku nije moguće obraditi.');image.src=event.target.result};reader.onerror=()=>toast('Datoteku nije moguće pročitati.');reader.readAsDataURL(file)}
const saveClientBaseWithLogo=saveClient;
saveClient=function(index){saveClientBaseWithLogo(index);const clients=getClients(),target=index===null?clients.length-1:index;if(target>=0&&clients[target]&&clients[target].logo!==clientLogoDraft){clients[target].logo=clientLogoDraft;saveClients(clients);renderClients?.()}};
const clientProfileBaseWithNoteActions=clientProfile;
clientProfile=function(index){clientProfileBaseWithNoteActions(index);const client=getClients()[index];if(!client)return;const notes=(client.timeline||[]).map((note,noteIndex)=>({note,noteIndex})).sort((a,b)=>String(b.note.date||'').localeCompare(String(a.note.date||''))),events=document.querySelectorAll('.timeline-event.note');events.forEach((event,eventIndex)=>{const entry=notes[eventIndex];if(!entry)return;event.insertAdjacentHTML('beforeend',`<div class="timeline-note-actions"><button class="btn light tiny" onclick="editClientTimelineNote(${index},${entry.noteIndex})">Uredi</button><button class="btn danger tiny" onclick="deleteClientTimelineNote(${index},${entry.noteIndex})">Obriši</button></div>`)})};
function editClientTimelineNote(clientIndex,noteIndex){const client=getClients()[clientIndex],note=client?.timeline?.[noteIndex];if(!note)return;openModal('Uredi bilješku',`<div class="field"><label>Bilješka</label><textarea id="clientTimelineNoteEdit" rows="5">${esc(note.detail||'')}</textarea></div>`,`<div class="modal-actions"><button class="btn light" onclick="clientProfile(${clientIndex})">Odustani</button><button class="btn accent" onclick="saveClientTimelineNoteEdit(${clientIndex},${noteIndex})">Sačuvaj izmjene</button></div>`)}
function saveClientTimelineNoteEdit(clientIndex,noteIndex){const detail=$('clientTimelineNoteEdit')?.value.trim();if(!detail){toast('Unesite bilješku.');return}const clients=getClients(),client=clients[clientIndex];if(!client?.timeline?.[noteIndex])return;client.timeline[noteIndex]={...client.timeline[noteIndex],detail};saveClients(clients);clientProfile(clientIndex);toast('Bilješka je ažurirana.')}
function deleteClientTimelineNote(clientIndex,noteIndex){const client=getClients()[clientIndex],note=client?.timeline?.[noteIndex];if(!note)return;confirmDestructive('Obrisati bilješku?',`Brišete bilješku „${String(note.detail||'').slice(0,80)}${String(note.detail||'').length>80?'…':''}“.`,()=>{const clients=getClients();clients[clientIndex].timeline.splice(noteIndex,1);saveClients(clients);clientProfile(clientIndex);toast('Bilješka je obrisana.')})}

/* Inline masovne radnje: checkbox kolona u postojećoj tabeli + leteći meni. */
let inlineBulkRoute='';
function inlineBulkConfig(route){return({invoices:{read:getInvoices,save:saveInvoices,key:item=>String(item.id),label:item=>item.number||'Faktura'},offers:{read:getOffers,save:saveOffers,key:item=>String(item.id),label:item=>item.number||'Ponuda'},clients:{read:getClients,save:saveClients,key:(_,index)=>String(index),label:item=>item.name||'Klijent'},catalog:{read:getCatalog,save:saveCatalog,key:(_,index)=>String(index),label:item=>item.name||'Stavka'},expenses:{read:()=>extGet('expenses'),save:rows=>extSet('expenses',rows),key:(_,index)=>String(index),label:item=>item.name||'Trošak'},projects:{read:()=>extGet('projects'),save:rows=>extSet('projects',rows),key:(_,index)=>String(index),label:item=>item.name||'Projekat'},tasks:{read:()=>extGet('tasks'),save:rows=>extSet('tasks',rows),key:(_,index)=>String(index),label:item=>item.name||'Zadatak'},documents:{read:()=>extGet('documents'),save:rows=>extSet('documents',rows),key:(_,index)=>String(index),label:item=>item.name||'Dokument'}})[route]}
function inlineBulkRowLabel(route,row){if(route==='catalog')return row.querySelector('td:nth-child(2) strong')?.textContent.trim()||'';if(route==='clients')return row.querySelector('.client-cell strong')?.textContent.trim()||'';return row.querySelector('td:first-child strong')?.textContent.trim()||''}
function inlineBulkActions(route){if(route==='invoices')return'<button class="btn light small" onclick="applyInlineBulk(\'sent\')">Poslano</button><button class="btn success small" onclick="applyInlineBulk(\'paid\')">Plaćeno</button>';if(route==='offers')return'<button class="btn light small" onclick="applyInlineBulk(\'sent\')">Poslano</button><button class="btn success small" onclick="applyInlineBulk(\'accepted\')">Prihvaćeno</button>';if(route==='catalog')return'<button class="btn success small" onclick="applyInlineBulk(\'active\')">Aktiviraj</button><button class="btn light small" onclick="applyInlineBulk(\'inactive\')">Deaktiviraj</button>';if(route==='tasks')return'<button class="btn success small" onclick="applyInlineBulk(\'done\')">Završeno</button><button class="btn light small" onclick="applyInlineBulk(\'open\')">Otvoreno</button>';return''}
function activateInlineBulk(route){const config=inlineBulkConfig(route),table=$('viewContainer')?.querySelector('.table');if(!config||!table){toast('Tabela trenutno nema stavki za odabir.');return}if(inlineBulkRoute===route){closeInlineBulk();return}closeInlineBulk();inlineBulkRoute=route;const rows=config.read();table.classList.add('bulk-mode');table.querySelector('thead tr')?.insertAdjacentHTML('afterbegin','<th class="bulk-select-cell"><input type="checkbox" aria-label="Označi sve" onchange="toggleInlineBulkAll(this.checked)"></th>');table.querySelectorAll('tbody tr').forEach(row=>{const label=inlineBulkRowLabel(route,row),match=rows.map((item,index)=>({item,index})).find(entry=>config.label(entry.item)===label),key=match?config.key(match.item,match.index):'';if(!key)return;row.insertAdjacentHTML('afterbegin',`<td class="bulk-select-cell"><input type="checkbox" class="inline-bulk-check" value="${esc(key)}" aria-label="Označi ${esc(label)}"></td>`)});document.body.insertAdjacentHTML('beforeend',`<div class="bulk-floating-menu" id="bulkFloatingMenu"><strong><span id="bulkSelectedCount">0</span> odabrano</strong>${inlineBulkActions(route)}<button class="btn danger small" onclick="applyInlineBulk('delete')">Obriši</button><button class="btn light small" onclick="closeInlineBulk()">Zatvori</button></div>`);table.querySelectorAll('.inline-bulk-check').forEach(check=>check.onchange=updateInlineBulkSelection);updateInlineBulkSelection()}
function toggleInlineBulkAll(checked){document.querySelectorAll('.inline-bulk-check').forEach(input=>{input.checked=checked});updateInlineBulkSelection()}
function updateInlineBulkSelection(){const selected=document.querySelectorAll('.inline-bulk-check:checked');document.querySelectorAll('.inline-bulk-check').forEach(input=>input.closest('tr')?.classList.toggle('bulk-selected',input.checked));if($('bulkSelectedCount'))$('bulkSelectedCount').textContent=selected.length}
function closeInlineBulk(){document.querySelectorAll('.bulk-select-cell').forEach(cell=>cell.remove());document.querySelectorAll('.bulk-selected').forEach(row=>row.classList.remove('bulk-selected'));$('bulkFloatingMenu')?.remove();inlineBulkRoute=''}
function applyInlineBulk(action){const route=inlineBulkRoute,config=inlineBulkConfig(route),keys=new Set([...document.querySelectorAll('.inline-bulk-check:checked')].map(input=>input.value));if(!config||!keys.size){toast('Označite barem jednu stavku.');return}const apply=()=>{let rows=config.read();if(action==='delete')rows=rows.filter((item,index)=>!keys.has(config.key(item,index)));else rows=rows.map((item,index)=>{if(!keys.has(config.key(item,index)))return item;if(route==='invoices')return{...item,status:action,paidAmount:action==='paid'?(+item.total||0):item.paidAmount};if(route==='offers')return{...item,status:action};if(route==='catalog')return{...item,active:action==='active'};if(route==='tasks')return{...item,done:action==='done'};return item});config.save(rows);closeInlineBulk();refreshCurrentView();updateInvoiceBadge?.();toast(action==='delete'?'Odabrane stavke su obrisane.':'Odabrane stavke su ažurirane.')};if(action==='delete'){const names=config.read().filter((item,index)=>keys.has(config.key(item,index))).map(config.label).join(', ');confirmDestructive('Obrisati odabrane stavke?',`Brišete: ${names}.`,apply)}else apply()}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||!button.textContent.includes('Masovne radnje'))return;const route=location.hash.slice(1)||'dashboard';if(route==='invoices')return;event.preventDefault();event.stopImmediatePropagation();activateInlineBulk(route)},true);
const navigateBeforeInlineBulk=navigate;
navigate=function(route){closeInlineBulk();return navigateBeforeInlineBulk(route)};
/* Fakture: filteri u jednom redu i isti A4 tok za štampu/PDF iz liste. */
invoiceRowActions=function(invoice){const status=effectiveStatus(invoice),id=JSON.stringify(String(invoice.id));return`<div class="row-actions action-texts invoice-actions"><span class="action-group"><button class="btn light tiny" onclick='editInvoice(${id})'>Uredi</button><button class="btn light tiny" onclick='duplicateInvoice(${id})'>⧉ Dupliciraj</button></span><span class="action-group"><button class="btn light tiny" onclick='printInvoiceById(${id})'>▣ Štampaj</button><button class="btn light tiny" onclick='emailInvoice(${id})'>✉ Pošalji</button></span><span class="action-group">${status!=='paid'&&status!=='cancelled'?`<button class="btn success tiny" onclick='markInvoicePaid(${id})'>✓ Plaćeno</button><button class="btn light tiny" onclick='recordPaymentModal(${id})'>＋ Uplata</button>`:''}</span>${status==='draft'?`<button class="btn danger tiny" onclick='deleteInvoice(${id})'>⌫ Obriši</button>`:status!=='cancelled'?`<button class="btn danger tiny" onclick='cancelInvoice(${id})'>⊘ Otkaži</button>`:''}</div>`};
const renderHistoryBaseWithToolbar=renderHistory;
renderHistory=function(){renderHistoryBaseWithToolbar();const toolbar=$('viewContainer')?.querySelector('.filter-toolbar');if(toolbar&&!toolbar.querySelector('.invoice-clear-filters'))toolbar.insertAdjacentHTML('beforeend','<button class="btn light invoice-clear-filters" onclick="clearInvoiceFilters()">Očisti filtere</button>')};
function restoreInvoiceActionView(route,invoice){
 if(route==='invoice'){
  const current=getInvoices().find(item=>String(item.id)===String(invoice.id))||invoice;
  renderInvoice(current);
  return;
 }
 navigate(routes[route]?route:'invoices');
}
printInvoiceById=async function(id){const invoice=getInvoices().find(item=>String(item.id)===String(id));if(!invoice)return;const returnRoute=location.hash.slice(1)||'invoices';renderInvoice(invoice);await new Promise(resolve=>requestAnimationFrame(resolve));await printCurrentInvoice();restoreInvoiceActionView(returnRoute,invoice)};
downloadInvoicePdfForEmail=async function(id){const invoice=getInvoices().find(item=>String(item.id)===String(id));if(!invoice)return;const returnRoute=location.hash.slice(1)||'invoices';closeModal();renderInvoice(invoice);await new Promise(resolve=>requestAnimationFrame(resolve));await downloadCurrentPdf();restoreInvoiceActionView(returnRoute,invoice)};
deleteInvoice=function(id){const invoice=getInvoices().find(item=>String(item.id)===String(id));if(!invoice)return;confirmDestructive('Obrisati fakturu?',`Trajno brišete fakturu „${invoice.number}“ za klijenta ${invoice.clientName||'bez klijenta'}.`,()=>{saveInvoices(getInvoices().filter(item=>String(item.id)!==String(id)));updateInvoiceBadge();renderHistory();toast('Faktura je obrisana.')})};
cancelInvoice=function(id){const invoice=getInvoices().find(item=>String(item.id)===String(id));if(!invoice)return;confirmAction(`Faktura „${invoice.number}“ za klijenta ${invoice.clientName||'bez klijenta'} bit će označena kao otkazana. Dokument ostaje sačuvan i status se kasnije može promijeniti.`,()=>saveInvoiceStatus(id,'cancelled'))};
exportInvoiceReport=function(){const rows=getInvoices(),groups=groupedCurrency(rows),paid=groupedCurrency(rows.filter(item=>effectiveStatus(item)==='paid')),overdue=groupedCurrency(rows.filter(isOverdue)),company=getCompany(),printWindow=window.open('','_blank','width=900,height=1000');if(!printWindow){toast('Dozvolite otvaranje prozora za izvještaj.');return}const totals=values=>Object.entries(values).map(([currency,value])=>money(value,currency)).join(' · ')||'0';printWindow.document.write(`<!doctype html><html lang="bs"><head><meta charset="utf-8"><title>Izvještaj faktura</title><style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;color:#243247;font-size:9px}.report-head{display:flex;justify-content:space-between;align-items:flex-start;padding-bottom:12px;border-bottom:2px solid #ff2742}.report-head h1{font-size:19px;margin:0 0 4px}.muted{color:#758195}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:14px 0}.summary div{padding:10px;border:1px solid #e4e9ef;border-radius:7px}.summary span,.summary strong{display:block}.summary span{font-size:7px;text-transform:uppercase;letter-spacing:.7px;color:#758195}.summary strong{font-size:11px;margin-top:4px}table{width:100%;border-collapse:collapse}th{text-transform:uppercase;letter-spacing:.5px;font-size:7px;color:#758195;background:#f4f6f8}th,td{text-align:left;padding:6px 7px;border-bottom:1px solid #e7ebf0}td:last-child,th:last-child{text-align:right}.status{font-weight:700}.foot{margin-top:12px;color:#758195;font-size:7px;text-align:right}</style></head><body><div class="report-head"><div><h1>Izvještaj faktura</h1><div class="muted">${esc(company.name||'Moja firma')}</div></div><div class="muted">Generisano ${esc(new Date().toLocaleDateString('bs-BA'))}</div></div><div class="summary"><div><span>Fakturisano</span><strong>${totals(groups)}</strong></div><div><span>Plaćeno</span><strong>${totals(paid)}</strong></div><div><span>Dospjelo</span><strong>${totals(overdue)}</strong></div></div><table><thead><tr><th>Broj</th><th>Klijent</th><th>Datum</th><th>Rok</th><th>Status</th><th>Iznos</th></tr></thead><tbody>${rows.map(item=>`<tr><td><strong>${esc(item.number)}</strong></td><td>${esc(item.clientName||'—')}</td><td>${esc(formatDate(item.issueDate))}</td><td>${esc(formatDate(item.dueDate))}</td><td class="status">${esc(statusLabel(effectiveStatus(item),isOverdue(item))[1])}</td><td>${money(item.total,item.currency)}</td></tr>`).join('')}</tbody></table><div class="foot">Ukupno ${rows.length} ${rows.length===1?'faktura':'faktura'} · Fakture / woxdzn.com</div></body></html>`);printWindow.document.close();setTimeout(()=>printWindow.print(),300)};

