function offerPrintHtml(){const paper=document.querySelector('#offerPreview .offer-live-preview');if(!paper)throw new Error('Pregled ponude nije dostupan.');const clone=paper.cloneNode(true),styles=[...document.querySelectorAll('link[rel="stylesheet"]')].map(link=>`<link rel="stylesheet" href="${esc(link.href)}">`).join('');return`<!doctype html><html lang="bs"><head><meta charset="utf-8"><title>Ponuda ${esc(offerState.number)}</title>${styles}<style>@page{size:A4;margin:0}html,body{width:210mm!important;min-height:297mm!important;margin:0!important;background:#fff!important}body>.sample-a4{margin:0!important;box-shadow:none!important}*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}tr,.sample-summary,.sample-bottom{break-inside:avoid}</style></head><body>${clone.outerHTML}</body></html>`}
printOffer=async function(){if($('ofNumber'))syncOffer();let temporary=null;if(!document.querySelector('#offerPreview .offer-live-preview')){temporary=document.createElement('div');temporary.id='offerPreview';temporary.style.cssText='position:fixed;left:-10000px;top:0;width:794px';document.body.appendChild(temporary);updateOfferPreview()}const printWindow=window.open('','_blank','width=900,height=1100');if(!printWindow){temporary?.remove();toast('Dozvolite otvaranje prozora za štampu.');return}try{const ready=new Promise(resolve=>printWindow.addEventListener('load',resolve,{once:true}));printWindow.document.open();printWindow.document.write(offerPrintHtml());printWindow.document.close();await ready;await printWindow.document.fonts.ready;await Promise.all([...printWindow.document.images].map(image=>image.decode()));printWindow.focus();printWindow.print()}catch(error){console.error(error);toast('Ponudu nije moguće pripremiti za štampu.')}finally{temporary?.remove()}};
