/* Kalendar: više izvora, napredna pretraga mjeseca i direktno otvaranje zapisa. */
let calendarSearchQuery='',calendarSearchTimer;
calendarEvents=function(){const invoices=getInvoices(),offers=getOffers(),tasks=extGet('tasks'),projects=extGet('projects'),expenses=extGet('expenses'),documents=extGet('documents'),recurring=fsGet('v12_recurring',[]);return[...invoices.flatMap(invoice=>[{date:invoice.issueDate,title:`Izdana faktura ${invoice.number}`,type:'invoice',entity:'invoice',id:invoice.id,detail:invoice.clientName},{date:invoice.dueDate,title:`Rok fakture ${invoice.number}`,type:'invoice',entity:'invoice',id:invoice.id,detail:money(Math.max(0,(+invoice.total||0)-paidAmount(invoice)),invoice.currency)},...(invoice.payments||[]).map(payment=>({date:payment.date,title:`Uplata · ${invoice.number}`,type:'paid',entity:'invoice',id:invoice.id,detail:money(payment.amount,invoice.currency)})),...(invoice.milestones||[]).map(milestone=>({date:milestone.dueDate,title:`${milestone.name||'Rata'} · ${invoice.number}`,type:milestone.status==='paid'?'paid':'invoice',entity:'invoice',id:invoice.id,detail:money(milestone.amount,invoice.currency)}))]),...offers.flatMap(offer=>[{date:offer.issueDate,title:`Kreirana ponuda ${offer.number}`,type:'offer',entity:'offer',id:offer.id,detail:offer.clientName},{date:offer.validUntil,title:`Ističe ponuda ${offer.number}`,type:'offer',entity:'offer',id:offer.id,detail:offer.clientName}]),...tasks.map((task,index)=>({date:task.due,title:`Zadatak · ${task.name}`,type:'task',entity:'task',id:index,detail:task.client||task.project||''})),...projects.map((project,index)=>({date:project.due,title:`Rok projekta · ${project.name}`,type:'project',entity:'project',id:index,detail:project.client||''})),...expenses.map((expense,index)=>({date:expense.date,title:`Trošak · ${expense.name}`,type:'expense',entity:'expense',id:index,detail:moneyValue(expense.amount,expense.currency||getSettings().currency)})),...documents.map((document,index)=>({date:document.date,title:`Dokument · ${document.name}`,type:'document',entity:'document',id:index,detail:document.type||''})),...recurring.map((item,index)=>({date:item.next,title:`Ponavljajuća faktura · ${item.client}`,type:'recurring',entity:'recurring',id:index,detail:item.description||''}))].filter(event=>event.date)};
function openCalendarEvent(entity,id){if(entity==='invoice')editInvoice(id);else if(entity==='offer')editOffer(id);else if(entity==='project')projectDetail(+id);else navigate(entity==='task'?'tasks':entity==='expense'?'expenses':entity==='document'?'documents':entity==='recurring'?'recurring':'calendar')}
function setCalendarMonth(value){if(value)calendarMonthCursor=value;renderCalendarFull()}
