renderCalendarFull=function(){const base=calendarMonthCursor?new Date(`${calendarMonthCursor}-01T12:00:00`):new Date(),month=`${base.getFullYear()}-${String(base.getMonth()+1).padStart(2,'0')}`,all=calendarEvents(),events=all.filter(event=>event.date.slice(0,7)===month&&(!calendarSearchQuery||`${event.title} ${event.detail||''} ${event.type}`.toLowerCase().includes(calendarSearchQuery))).sort((a,b)=>a.date.localeCompare(b.date)),days=new Date(base.getFullYear(),base.getMonth()+1,0).getDate(),label=new Intl.DateTimeFormat('bs-BA',{month:'long',year:'numeric'}).format(base);$('viewContainer').innerHTML=`<div class="page"><div class="page-heading"><div><h1>Kalendar</h1><p class="page-subtitle">Fakture, uplate, ponude, zadaci, projekti, troškovi i dokumenti na jednom mjestu.</p></div></div><div class="calendar-tools"><button class="btn light" onclick="changeCalendarMonth(-1)">← Prethodni</button><label class="field calendar-month-picker"><span>Mjesec</span><input type="month" value="${month}" onchange="setCalendarMonth(this.value)"></label><button class="btn light" onclick="changeCalendarMonth(1)">Sljedeći →</button><div class="filter-search-wrap"><span>⌕</span><input id="calendarSearch" value="${esc(calendarSearchQuery)}" placeholder="Pretraži događaje mjeseca..." oninput="setCalendarSearch(this.value)"></div></div><div class="calendar-overview-layout"><div class="card card-pad calendar-textual-card"><div class="section-head"><div><h2>${esc(label)}</h2><p class="page-subtitle">${events.length} događaja</p></div></div><div class="calendar-list">${events.length?events.map(event=>`<button class="calendar-event calendar-event-button" onclick="openCalendarEvent('${event.entity}','${esc(event.id)}')"><span class="calendar-dot ${event.type}"></span><span class="calendar-event-copy"><strong>${esc(event.title)}</strong><small>${esc(formatDate(event.date))}${event.detail?` · ${esc(event.detail)}`:''}</small></span><span class="calendar-open">Otvori →</span></button>`).join(''):'<div class="empty">Nema događaja za odabrani mjesec i pretragu.</div>'}</div></div><div class="card card-pad calendar-visual-card"><div class="section-head"><div><h2>Pregled mjeseca</h2><p class="page-subtitle">Kliknite događaj za otvaranje zapisa.</p></div></div><div class="calendar-day-grid">${Array.from({length:days},(_,index)=>{const date=`${month}-${String(index+1).padStart(2,'0')}`,items=events.filter(event=>event.date===date);return`<div class="calendar-day"><strong>${index+1}</strong>${items.map(event=>`<button class="calendar-day-event ${event.type}" onclick="openCalendarEvent('${event.entity}','${esc(event.id)}')">${esc(event.title)}</button>`).join('')}</div>`}).join('')}</div></div></div></div>`}
const renderCalendarFullLocaleBase=renderCalendarFull;
