/* Ponavljajuće fakture koriste puni editor, ali šablon ne ulazi u listu Faktura. */
let recurringTemplateContext=null,recurringPreviousDraft=null;
function recurringTemplateData(source=null){const settings=getSettings(),data=source?.template?JSON.parse(JSON.stringify(source.template)):null;return data||{number:'ŠABLON',issueDate:today(),dueDate:addDays(today(),settings.dueDays),status:'draft',currency:settings.currency,paymentMethod:settings.paymentMethod,clientId:'',clientName:'',clientAddress:'',clientCity:'',clientCountry:'',clientEmail:'',clientIdNo:'',clientVat:'',globalDiscountType:'percent',globalDiscount:0,items:[defaultItem()],milestones:[],note:settings.paymentNote}}
function showRecurringTemplateEditor(index=null){const schedules=fsGet('v12_recurring',[]),source=index===null?null:schedules[index];recurringPreviousDraft=JSON.parse(JSON.stringify(getDraft()||null));recurringTemplateContext={index,period:source?.period||'Mjesečno',next:source?.next||today(),active:source?.active!==false};renderInvoice(recurringTemplateData(source));const heading=$('viewContainer')?.querySelector('.page-heading h1');if(heading)heading.textContent=index===null?'Novi raspored fakture':'Uredi raspored fakture';const editor=$('viewContainer')?.querySelector('.invoice-editor');if(editor)editor.insertAdjacentHTML('afterbegin',`<div class="card section-card recurring-template-card"><div class="section-head"><div><h3>Postavke rasporeda</h3><p class="page-subtitle">Ovaj dokument je šablon i neće biti spremljen u Fakture.</p></div><span class="status-pill status-sent">Šablon</span></div><div class="grid-3"><div class="field"><label>Period</label><select id="recurringPeriod"><option>Mjesečno</option><option>Kvartalno</option><option>Polugodišnje</option><option>Godišnje</option></select></div><div class="field"><label>Prva sljedeća faktura</label><input id="recurringNext" type="date" value="${esc(recurringTemplateContext.next)}"></div><div class="field"><label>Status rasporeda</label><select id="recurringActive"><option value="true">Aktivno</option><option value="false">Pauzirano</option></select></div></div></div>`);$('recurringPeriod').value=recurringTemplateContext.period;$('recurringActive').value=String(recurringTemplateContext.active);const actions=$('viewContainer')?.querySelector('.page-actions');if(actions)actions.innerHTML=`<button class="btn light" onclick="cancelRecurringTemplate()">Odustani</button><button class="btn accent" onclick="saveRecurringTemplate()">Sačuvaj raspored</button>`}
addRecurring=function(){showRecurringTemplateEditor()};
