function saveRecurringTemplate(){syncInvoiceFromForm();if(!validateInvoice())return;const totals=invoiceTotals(invoiceState.items,invoiceState.globalDiscountType,invoiceState.globalDiscount),schedules=fsGet('v12_recurring',[]),record={client:invoiceState.clientName,description:invoiceState.items[0]?.description||'Ponavljajuća faktura',amount:totals.total,currency:invoiceState.currency,period:$('recurringPeriod').value,next:$('recurringNext').value,active:$('recurringActive').value==='true',template:JSON.parse(JSON.stringify({...invoiceState,id:undefined,number:'ŠABLON'})),updatedAt:Date.now()};if(recurringTemplateContext.index===null)schedules.unshift(record);else schedules[recurringTemplateContext.index]={...schedules[recurringTemplateContext.index],...record};const previous=recurringPreviousDraft;fsSet('v12_recurring',schedules);recurringTemplateContext=null;recurringPreviousDraft=null;saveDraft(previous);navigate('recurring');toast('Raspored i šablon fakture su sačuvani.')}
function duplicateRecurring(index){const schedules=fsGet('v12_recurring',[]),source=schedules[index];if(!source)return;schedules.splice(index+1,0,{...JSON.parse(JSON.stringify(source)),client:`${source.client} · kopija`,active:false,next:source.next,updatedAt:Date.now()});fsSet('v12_recurring',schedules);renderRecurring();toast('Raspored je dupliciran kao pauziran.')}
