const renderRecurringBaseWithActions=renderRecurring;
renderRecurring=function(){renderRecurringBaseWithActions();document.querySelectorAll('#viewContainer tbody tr').forEach((row,index)=>{const actions=row.querySelector('.recurring-actions');if(actions)actions.insertAdjacentHTML('beforeend',`<button class="btn light tiny" onclick="editRecurring(${index})">Uredi</button><button class="btn light tiny" onclick="duplicateRecurring(${index})">Dupliciraj</button><button class="btn danger tiny" onclick="deleteRecurring(${index})">Obriši</button>`)})};
