/* A4 pagination is shared by the live preview, print view and PDF export. */
function documentRowGroups(rowHeights,firstFinal,firstOpen,nextFinal,nextOpen){
 const groups=[];let cursor=0,first=true;
 while(cursor<rowHeights.length){
  const finalCapacity=first?firstFinal:nextFinal,openCapacity=first?firstOpen:nextOpen;
  const remaining=rowHeights.slice(cursor).reduce((sum,height)=>sum+height,0);
  /* Jedna preostala stavka uvijek pripada trenutnoj stranici. Ovo sprječava
     praznu prvu stranicu kada su footer ili duga napomena visoki. */
  if(remaining<=finalCapacity||rowHeights.length-cursor===1){groups.push(rowHeights.slice(cursor).map((_,index)=>cursor+index));break}
  let used=0,end=cursor;
  /* Međustranica nikada ne smije potrošiti i posljednji red: tada bi se
     završni sažetak naknadno dodao na stranicu mjerenu bez sažetka. */
  /* Popuni trenutnu stranicu do stvarnog kapaciteta. Jedna stavka smije ostati
     na završnoj stranici uz obračun; umjetno ostavljanje dvije stavke je
     stvaralo vidljivo prazan prostor neposredno nakon prijeloma. */
  while(end<rowHeights.length-1&&(used+rowHeights[end]<=openCapacity||end===cursor)){used+=rowHeights[end];end++}
  if(end===cursor)end=Math.min(cursor+1,rowHeights.length);
  groups.push(Array.from({length:end-cursor},(_,index)=>cursor+index));cursor=end;first=false;
 }
 return groups.length?groups:[[]]
}
function paginateA4Preview(hostSelector,paperSelector,documentName){
 const host=document.querySelector(hostSelector),source=host?.querySelector(paperSelector);if(!host||!source||source.closest('.document-pages'))return;
 const rows=[...source.querySelectorAll('tbody tr')];if(!rows.length)return;
 const staging=document.createElement('div');staging.className='document-pagination-stage';const measure=source.cloneNode(true);staging.appendChild(measure);document.body.appendChild(staging);
 /* offsetHeight daje stvarnu A4 layout visinu. getBoundingClientRect je ranije
    vraćao skaliranu visinu live-preview elementa i zato je paginator računao
    da na stranicu stane više redova nego što fizički može stati. */
 const outer=element=>{if(!element)return 0;const style=getComputedStyle(element),flexibleAutoFooter=(measure.classList.contains('template-studio')||measure.classList.contains('template-editorial')||measure.classList.contains('template-soft')||measure.classList.contains('template-frame')||measure.classList.contains('template-accent'))&&element.classList.contains('sample-bottom');return element.offsetHeight+(flexibleAutoFooter?0:(parseFloat(style.marginTop)||0))+(parseFloat(style.marginBottom)||0)};
 const style=getComputedStyle(measure),contentHeight=1123-(parseFloat(style.paddingTop)||0)-(parseFloat(style.paddingBottom)||0),topHeight=outer(measure.querySelector('.sample-top')),partiesHeight=outer(measure.querySelector('.sample-parties')),headHeight=outer(measure.querySelector('thead')),summaryHeight=outer(measure.querySelector('.sample-summary')),bottomHeight=outer(measure.querySelector('.sample-bottom')),continuationHeight=38,rowHeights=[...measure.querySelectorAll('tbody tr')].map(row=>Math.max(34,outer(row)));
 staging.remove();
 /* Međustranice moraju ostaviti zaseban prostor za oznaku nastavka i broj
    stranice. Nastavne stranice koriste kompaktno zaglavlje umjesto ponavljanja
    punog zaglavlja firme, pa se njegova visina ne oduzima drugi put. */
 const safety=34,pageFooterReserve=124;
 const compactContinuationGain=measure.classList.contains('template-studio')?64:0;
 const firstFinal=contentHeight-topHeight-partiesHeight-headHeight-summaryHeight-bottomHeight-safety;
 const firstOpen=contentHeight-topHeight-partiesHeight-headHeight-pageFooterReserve;
 const nextFinal=contentHeight-continuationHeight-headHeight-summaryHeight-bottomHeight-safety+compactContinuationGain;
 const nextOpen=contentHeight-continuationHeight-headHeight-pageFooterReserve+compactContinuationGain;
 const groups=documentRowGroups(rowHeights,firstFinal,firstOpen,nextFinal,nextOpen);if(groups.length===1)return;
 const wrapper=document.createElement('div');wrapper.className='document-pages';
 const showPageNumbers=getAppearance?.().showPageNumbers!==false;
 groups.forEach((indexes,pageIndex)=>{const page=source.cloneNode(true),body=page.querySelector('tbody'),pageRows=[...page.querySelectorAll('tbody tr')];body.innerHTML='';indexes.forEach(index=>body.appendChild(pageRows[index]));page.classList.add('document-page');if(pageIndex){page.classList.add('document-continuation');page.querySelector('.sample-parties')?.remove();page.querySelector('.sample-top')?.replaceWith(Object.assign(document.createElement('div'),{className:'document-continuation-head',innerHTML:`<strong>${esc(documentName)}</strong><span>Nastavak stavki</span>`}))}if(pageIndex<groups.length-1){page.classList.add('document-intermediate');page.querySelector('.sample-summary')?.remove();page.querySelector('.sample-bottom')?.remove();page.insertAdjacentHTML('beforeend',`<div class="document-continued-footer">Nastavak na sljedećoj stranici</div>`)}else page.classList.add('document-final');if(showPageNumbers)page.insertAdjacentHTML('beforeend',`<span class="document-page-number">Stranica ${pageIndex+1} / ${groups.length}</span>`);wrapper.appendChild(page)});
 host.innerHTML='';host.appendChild(wrapper)
}
const updatePreviewBeforePagination=updatePreview;
updatePreview=function(){updatePreviewBeforePagination();paginateA4Preview('#a4Preview','.invoice-live-preview',`Faktura ${invoiceState.number||'—'}`)};
const updateOfferPreviewBeforePagination=updateOfferPreview;
updateOfferPreview=function(){updateOfferPreviewBeforePagination();paginateA4Preview('#offerPreview','.offer-live-preview',`Ponuda ${offerState.number||'—'}`)};
function documentPagesHtml(hostSelector){const pages=[...document.querySelectorAll(`${hostSelector} .sample-a4`)];if(!pages.length)throw new Error('Pregled dokumenta nije otvoren.');const wrapper=document.createElement('div');wrapper.className='document-pages print-document-pages';pages.forEach(page=>{const clone=page.cloneNode(true);clone.style.setProperty('--brand-doc',getBrandColor());wrapper.appendChild(clone)});return wrapper.outerHTML}
function documentPrintStyles(){return`<style>@page{size:A4;margin:0}html,body{display:block!important;width:210mm!important;height:auto!important;min-height:0!important;margin:0!important;padding:0!important;overflow:visible!important;background:#fff!important}.print-document-pages{display:block!important;width:210mm!important;height:auto!important;margin:0!important;padding:0!important;overflow:visible!important}.print-document-pages>.document-page{display:block!important;box-sizing:border-box!important;width:210mm!important;min-width:210mm!important;max-width:210mm!important;height:297mm!important;min-height:297mm!important;max-height:297mm!important;margin:0!important;overflow:hidden!important;box-shadow:none!important;break-inside:avoid!important;page-break-inside:avoid!important;break-after:page!important;page-break-after:always!important}.print-document-pages>.document-page:last-child{break-after:auto!important;page-break-after:auto!important}*{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}</style>`}
invoiceHtmlForDocument=function(){const styles=[...document.querySelectorAll('link[rel="stylesheet"]')].map(link=>`<link rel="stylesheet" href="${esc(link.href)}">`).join('');return`<!doctype html><html lang="bs"><head><meta charset="utf-8"><title>Faktura ${esc(invoiceState.number)}</title>${styles}${documentPrintStyles()}</head><body>${documentPagesHtml('#a4Preview')}</body></html>`};
offerPrintHtml=function(){const styles=[...document.querySelectorAll('link[rel="stylesheet"]')].map(link=>`<link rel="stylesheet" href="${esc(link.href)}">`).join('');return`<!doctype html><html lang="bs"><head><meta charset="utf-8"><title>Ponuda ${esc(offerState.number)}</title>${styles}${documentPrintStyles()}</head><body>${documentPagesHtml('#offerPreview')}</body></html>`};
downloadCurrentPdf=async function(){if(invoicePdfBusy)return;syncInvoiceFromForm();if(!validateInvoice())return;invoicePdfBusy=true;let holder;try{if(!window.jspdf?.jsPDF)throw new Error('PDF modul nije učitan. Provjerite internet vezu.');const capture=await loadInvoiceCanvas();await document.fonts.ready;const sources=[...document.querySelectorAll('#a4Preview .sample-a4')];if(!sources.length)throw new Error('Otvorite pregled fakture prije izvoza.');holder=document.createElement('div');holder.className='document-pdf-stage';document.body.appendChild(holder);const pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4',compress:true});for(let index=0;index<sources.length;index++){const clone=sources[index].cloneNode(true);holder.innerHTML='';holder.appendChild(clone);await Promise.all([...clone.querySelectorAll('img')].map(image=>image.decode()));const canvas=await capture(clone,{scale:2,backgroundColor:'#ffffff',useCORS:true,logging:false});if(index)pdf.addPage();pdf.addImage(canvas.toDataURL('image/png'),'PNG',0,0,210,297)}pdf.save('faktura-'+String(invoiceState.number).replace(/[^a-z0-9_-]/gi,'-')+'.pdf');toast(`PDF fakture (${sources.length} ${sources.length===1?'stranica':'stranice'}) je preuzet.`)}catch(error){console.error(error);toast(error.message||'PDF nije moguće generisati.')}finally{holder?.remove();invoicePdfBusy=false}};
setTimeout(()=>navigate(location.hash.slice(1)||'dashboard'),0);

/* IDs are stable even when list markup changes (links replaced the old <strong> cells). */
findExactSearchRow=function(type,id){const selector=type==='invoice'?`[data-invoice-id="${CSS.escape(String(id))}"]`:type==='offer'?`[data-offer-id="${CSS.escape(String(id))}"]`:'';const exact=selector&&document.querySelector(`#viewContainer ${selector}`);if(exact)return exact;const rows=[...document.querySelectorAll('#viewContainer table tbody tr')],record=type==='offer'?getOffers().find(row=>String(row.id)===String(id)):null;if(type==='offer')return rows.find(row=>row.textContent.includes(record?.number||''));if(type==='client')return rows.find(row=>row.textContent.includes(String(id)));if(type==='catalog'){const item=getCatalog().find(row=>String(row.code||row.name)===String(id));return rows.find(row=>row.textContent.includes(item?.name||''))}return null};

/* Završne korekcije nakon korisničkog testiranja. */
function ensureWorkspaceActions(route){
 const heading=$('viewContainer')?.querySelector('.page-heading');if(!heading)return;
 let actions=heading.querySelector('.page-actions');
 if(!actions){actions=document.createElement('div');actions.className='page-actions';heading.appendChild(actions)}
 [...heading.querySelectorAll(':scope > button')].forEach(button=>actions.appendChild(button));
 if(!actions.querySelector('.bulk-launch'))actions.insertAdjacentHTML('afterbegin',`<button class="btn light bulk-launch" onclick="activateInlineBulk('${route}')">☷ Masovne radnje</button>`)
}

activateInlineBulk=function(route){
 const config=inlineBulkConfig(route);if(!config)return;
 const rows=config.read();
 if(!rows.length){closeInlineBulk();toast('Tabela je prazna. Nema stavki za masovne radnje.');return}
 if(inlineBulkRoute===route){closeInlineBulk();return}
 closeInlineBulk();inlineBulkRoute=route;
 const table=$('viewContainer')?.querySelector('.table'),cards=[...($('viewContainer')?.querySelectorAll('[data-bulk-key]')||[])];
 if(table){
  table.classList.add('bulk-mode');table.querySelector('thead tr')?.insertAdjacentHTML('afterbegin','<th class="bulk-select-cell"><input type="checkbox" aria-label="Označi sve" onchange="toggleInlineBulkAll(this.checked)"></th>');
  table.querySelectorAll('tbody tr').forEach(row=>{
   const label=inlineBulkRowLabel(route,row);
   const match=rows.map((item,index)=>({item,index})).find(entry=>{
    if(route==='documents')return row.hasAttribute('data-bulk-key')&&config.key(entry.item,entry.index)===row.dataset.bulkKey;
    if(route==='expenses')return String(entry.item.id)===row.dataset.bulkKey;
    if(route==='offers')return String(entry.item.id)===row.dataset.offerId;
    if(route==='proformas')return String(entry.item.id)===row.dataset.proformaId&&!entry.item.invoiceId&&entry.item.status!=='converted';
    return config.label(entry.item)===label;
   });
   const key=match?config.key(match.item,match.index):'';
   row.insertAdjacentHTML('afterbegin',`<td class="bulk-select-cell">${key!==''?`<input type="checkbox" class="inline-bulk-check" value="${esc(key)}" aria-label="Označi ${esc(match?config.label(match.item):label)}">`:''}</td>`);
  });
  if(!table.querySelector('.inline-bulk-check')){closeInlineBulk();toast('Nema stavki u trenutnom filteru za masovne radnje.');return}
 }else if(cards.length){
  cards.forEach(card=>{card.classList.add('bulk-card-mode');card.insertAdjacentHTML('afterbegin',`<label class="bulk-card-select" onclick="event.stopPropagation()"><input type="checkbox" class="inline-bulk-check" value="${esc(card.dataset.bulkKey)}" aria-label="Označi stavku"></label>`)})
 }else{inlineBulkRoute='';toast('Tabela je prazna. Nema stavki za masovne radnje.');return}
 document.body.insertAdjacentHTML('beforeend',`<div class="bulk-floating-menu" id="bulkFloatingMenu"><strong><span id="bulkSelectedCount">0</span> odabrano</strong>${inlineBulkActions(route)}<button class="btn danger small" onclick="applyInlineBulk('delete')">Obriši</button><button class="btn light small" onclick="closeInlineBulk()">Zatvori</button></div>`);
 document.querySelectorAll('.inline-bulk-check').forEach(check=>check.onchange=updateInlineBulkSelection);updateInlineBulkSelection()
};
closeInlineBulk=function(){document.querySelectorAll('.bulk-select-cell,.bulk-card-select').forEach(cell=>cell.remove());document.querySelectorAll('.bulk-selected,.bulk-card-mode,.bulk-mode').forEach(row=>row.classList.remove('bulk-selected','bulk-card-mode','bulk-mode'));$('bulkFloatingMenu')?.remove();inlineBulkRoute=''};
updateInlineBulkSelection=function(){const selected=document.querySelectorAll('.inline-bulk-check:checked');document.querySelectorAll('.inline-bulk-check').forEach(input=>{const target=input.closest('tr,[data-bulk-key]');target?.classList.toggle('bulk-selected',input.checked)});if($('bulkSelectedCount'))$('bulkSelectedCount').textContent=selected.length};

function clientChoices(id,value=''){return`<input id="${id}" list="${id}Options" value="${esc(value)}" placeholder="Upišite ili odaberite klijenta"><datalist id="${id}Options">${getClients().map(client=>`<option value="${esc(client.name||'')}">${esc([client.email,client.city].filter(Boolean).join(' · '))}</option>`).join('')}</datalist>`}

renderExpenses=(function(base){return function(){base();ensureWorkspaceActions('expenses')}})(renderExpenses);

renderProjects=function(){
 const projects=extGet('projects'),tasks=extGet('tasks');
 $('viewContainer').innerHTML=`<div class="page"><div class="page-heading"><div><h1>Projekti</h1><p class="page-subtitle">Povežite klijente, rokove, budžete i zadatke u jedan pregled.</p></div><div class="page-actions"><button class="btn accent" onclick="addProject()">＋ Novi projekat</button></div></div><div class="project-grid">${projects.length?projects.map((project,index)=>{const related=tasks.filter(task=>task.project===project.name),done=related.filter(task=>task.done).length;return`<article class="feature-card project-card-rich" data-bulk-key="${index}"><div class="project-card-head"><span class="feature-icon blue">◈</span><div><strong>${esc(project.name)}</strong><small>${esc(project.client||'Bez klijenta')}</small></div></div><div class="project-card-details"><span><small>Budžet</small><strong>${moneyValue(project.budget||0,project.currency||getSettings().currency)}</strong></span><span><small>Rok</small><strong>${project.due?esc(formatDate(project.due)):'Nije zadan'}</strong></span><span><small>Zadaci</small><strong>${done}/${related.length}</strong></span></div>${project.note?`<p>${esc(project.note)}</p>`:''}<div class="row-actions"><button class="btn light small" onclick="projectDetail(${index})">Pregled</button><button class="btn danger small" onclick="deleteProject(${index})">Obriši</button></div></article>`}).join(''):'<div class="empty feature-empty">Još nema projekata.</div>'}</div></div>`;ensureWorkspaceActions('projects')
};
addProject=function(){openModal('Novi projekat',`<div class="grid-2"><div class="field"><label>Naziv projekta</label><input id="prName"></div><div class="field"><label>Klijent</label>${clientChoices('prClient')}</div><div class="field"><label>Budžet</label><input id="prBudget" type="number" min="0" step="0.01"></div><div class="field"><label>Valuta</label><select id="prCurrency"><option>BAM</option><option>EUR</option><option>USD</option><option>CHF</option></select></div><div class="field"><label>Rok</label><input id="prDue" type="date"></div><div class="field"><label>Napomena</label><input id="prNote"></div></div>`,`<div class="modal-actions"><button class="btn light" onclick="closeModal()">Odustani</button><button class="btn accent" onclick="saveProject()">Kreiraj</button></div>`)};

renderTasks=function(){
 const tasks=extGet('tasks');
 const column=(done,label)=>`<div class="task-col"><h3>${label} <span>${tasks.filter(task=>!!task.done===done).length}</span></h3>${tasks.map((task,index)=>({task,index})).filter(entry=>!!entry.task.done===done).map(({task,index})=>taskCard(task,index)).join('')||`<div class="empty">Nema ${done?'završenih':'otvorenih'} zadataka.</div>`}</div>`;
 $('viewContainer').innerHTML=`<div class="page"><div class="page-heading"><div><h1>Zadaci</h1><p class="page-subtitle">Interni zadaci, rokovi i povezani klijenti i projekti.</p></div><div class="page-actions"><button class="btn accent" onclick="addTask()">＋ Novi zadatak</button></div></div><div class="task-board">${column(false,'Otvoreno')}${column(true,'Završeno')}</div></div>`;ensureWorkspaceActions('tasks')
};
taskCard=function(task,index){return`<article class="task-card task-card-rich" data-bulk-key="${index}"><div class="task-card-copy"><strong>${esc(task.name)}</strong>${task.note?`<p>${esc(task.note)}</p>`:''}<div class="task-meta"><span>Klijent: <b>${esc(task.client||'—')}</b></span><span>Projekt: <b>${esc(task.project||'—')}</b></span><span>Rok: <b>${task.due?esc(formatDate(task.due)):'Nije zadan'}</b></span><span>Prioritet: <b>${esc(task.priority||'Normalan')}</b></span></div></div><div class="task-card-actions"><button class="btn ${task.done?'light':'success'} tiny" onclick="toggleTask(${index})">${task.done?'Vrati':'Završi'}</button><button class="btn light tiny" onclick="editTask(${index})">Uredi</button><button class="btn danger tiny" onclick="deleteTask(${index})">Obriši</button></div></article>`};
addTask=function(index=null){const task=index===null?{name:'',client:'',project:'',due:'',note:'',priority:'Normalan'}:extGet('tasks')[index];if(!task)return;openModal(index===null?'Novi zadatak':'Uredi zadatak',`<div class="grid-2"><div class="field"><label>Zadatak</label><input id="taName" value="${esc(task.name||'')}"></div><div class="field"><label>Klijent</label>${clientChoices('taClient',task.client||'')}</div><div class="field"><label>Projekt</label><input id="taProject" list="taProjectOptions" value="${esc(task.project||'')}"><datalist id="taProjectOptions">${extGet('projects').map(project=>`<option value="${esc(project.name)}"></option>`).join('')}</datalist></div><div class="field"><label>Rok</label><input id="taDue" type="date" value="${esc(task.due||'')}"></div><div class="field"><label>Prioritet</label><select id="taPriority"><option>Normalan</option><option>Visok</option><option>Nizak</option></select></div><div class="field"><label>Detalji</label><textarea id="taNote">${esc(task.note||'')}</textarea></div></div>`,`<div class="modal-actions"><button class="btn light" onclick="closeModal()">Odustani</button><button class="btn accent" onclick="saveTask(${index===null?'null':index})">Sačuvaj</button></div>`);$('taPriority').value=task.priority||'Normalan'};
function editTask(index){addTask(index)}
saveTask=function(index=null){const name=$('taName').value.trim();if(!name){toast('Unesite zadatak.');return}const tasks=extGet('tasks'),current=index===null?{}:tasks[index]||{};const task={...current,name,client:$('taClient').value.trim(),project:$('taProject').value.trim(),due:$('taDue').value,note:$('taNote').value.trim(),priority:$('taPriority').value,done:!!current.done};if(index===null)tasks.push(task);else tasks[index]=task;extSet('tasks',tasks);closeModal();renderTasks();toast(index===null?'Zadatak je kreiran.':'Zadatak je ažuriran.')};

renderDocuments=function(){
 const invoices=getInvoices(),offers=getOffers(),documents=extGet('documents'),rows=[...invoices.map(item=>({kind:'invoice',name:item.number,type:'Faktura',client:item.clientName,status:statusLabel(effectiveStatus(item),isOverdue(item))[1],id:item.id})),...offers.map(item=>({kind:'offer',name:item.number,type:'Ponuda',client:item.clientName,status:item.status||'Nacrt',id:item.id})),...documents.map((item,index)=>({kind:'attachment',name:item.name,type:item.type||'Prilog',client:item.client||'—',status:item.file||'Prilog',id:index,note:item.note||'',location:item.location||''}))];
 $('viewContainer').innerHTML=`<div class="page"><div class="page-heading"><div><h1>Dokumenti</h1><p class="page-subtitle">Centralni pregled izdanih dokumenata i lokalno evidentiranih priloga.</p></div><div class="page-actions"><button class="btn accent" onclick="addDocumentRecord()">＋ Dodaj prilog</button></div></div><div class="feature-grid"><div class="feature-stat"><span>Fakture</span><strong>${invoices.length}</strong><small>izdanih dokumenata</small></div><div class="feature-stat"><span>Ponude</span><strong>${offers.length}</strong><small>ponuda</small></div><div class="feature-stat"><span>Prilozi</span><strong>${documents.length}</strong><small>lokalno evidentiranih</small></div></div><div class="card card-pad"><div class="table-wrap"><table class="table"><thead><tr><th>Dokument</th><th>Tip</th><th>Klijent</th><th>Status / datoteka</th><th class="actions-head">RADNJE</th></tr></thead><tbody>${rows.length?rows.map(row=>{const id=JSON.stringify(String(row.id));return`<tr><td><strong>${esc(row.name)}</strong>${row.note?`<small class="cell-sub">${esc(row.note)}</small>`:''}</td><td>${esc(row.type)}</td><td>${esc(row.client||'—')}</td><td>${esc(row.status)}${row.location?`<small class="cell-sub document-location">${esc(row.location)}</small>`:''}</td><td class="actions-head">${row.kind==='invoice'?`<button class="btn light tiny" onclick='editInvoice(${id})'>Otvori</button>`:row.kind==='offer'?`<button class="btn light tiny" onclick='editOffer(${id})'>Otvori</button>`:`<button class="btn danger tiny" onclick="deleteDocumentRecord(${row.id})">Obriši</button>`}</td></tr>`}).join(''):'<tr><td colspan="5"><div class="empty">Nema dokumenata.</div></td></tr>'}</tbody></table></div></div></div>`;ensureWorkspaceActions('documents')
};
addDocumentRecord=function(){openModal('Dodaj prilog',`<div class="grid-2"><div class="field"><label>Naziv dokumenta</label><input id="doName" placeholder="Ugovor / račun / dokaz"></div><div class="field"><label>Klijent</label>${clientChoices('doClient')}</div><div class="field"><label>Tip</label><select id="doType"><option>Ugovor</option><option>Primljena faktura</option><option>Potvrda</option><option>Ostalo</option></select></div><div class="field"><label>Datum</label><input id="doDate" type="date" value="${today()}"></div><div class="field"><label>Napomena</label><input id="doNote"></div><div class="field"><label>Lokacija na računaru</label><input id="doLocation" placeholder="npr. Dokumenti/Ugovori"></div></div><div class="field"><label>Datoteka</label><input id="doFile" type="file"></div>`,`<div class="modal-actions"><button class="btn light" onclick="closeModal()">Odustani</button><button class="btn accent" onclick="saveDocumentRecord()">Sačuvaj</button></div>`)};
saveDocumentRecord=function(){const name=$('doName').value.trim();if(!name){toast('Unesite naziv dokumenta.');return}const documents=extGet('documents');documents.unshift({name,client:$('doClient').value.trim(),type:$('doType').value,note:$('doNote').value.trim(),file:$('doFile').files?.[0]?.name||'',date:$('doDate').value||today(),location:$('doLocation').value.trim()});extSet('documents',documents);closeModal();renderDocuments();toast('Prilog je evidentiran.')};

routes.expenses=renderExpenses;routes.projects=renderProjects;routes.tasks=renderTasks;routes.documents=renderDocuments;

const renderOfferEditorFinalBase=renderOfferEditor;
renderOfferEditor=function(data=null){
 renderOfferEditorFinalBase(data);$('offerClientSelect')?.remove();
 const card=$('ofClient')?.closest('.section-card'),grid=$('ofClient')?.closest('.grid-3');if(!card||!grid||$('offerClientPicker'))return;
 card.querySelector('.section-head')?.insertAdjacentHTML('beforeend','<button class="btn light small" onclick="clientModal()">＋ Novi klijent</button>');
 grid.insertAdjacentHTML('beforebegin',`<div class="client-picker offer-client-picker"><div id="offerClientPicker" class="client-picker-box ${offerState.clientName?'':'placeholder'}" onclick="toggleOfferClientPicker()"><span>${esc(offerState.clientName||'Odaberi sačuvanog klijenta...')}</span></div><button class="btn light" onclick="clearOfferClient()">Očisti</button><div id="offerClientDropdown" class="client-picker-dropdown" style="display:none"><div class="client-picker-search"><input id="offerClientPickerSearch" placeholder="Pretraži klijente..."></div><div id="offerClientOptions"></div></div></div>`);
 $('offerClientPickerSearch').oninput=renderOfferClientOptions;renderOfferClientOptions()
};
function toggleOfferClientPicker(){const dropdown=$('offerClientDropdown');if(!dropdown)return;dropdown.style.display=dropdown.style.display==='none'?'block':'none';if(dropdown.style.display==='block')$('offerClientPickerSearch')?.focus()}
function renderOfferClientOptions(){const box=$('offerClientOptions');if(!box)return;const query=($('offerClientPickerSearch')?.value||'').trim().toLowerCase(),clients=getClients().map((client,index)=>({client,index})).filter(({client})=>`${client.name||''} ${client.email||''} ${client.city||''} ${client.country||''}`.toLowerCase().includes(query));box.innerHTML=clients.length?`<div class="invoice-client-picker-head"><span>Klijent</span><span>Kontakt</span><span>Lokacija</span></div>${clients.map(({client,index})=>{const color=clientAvatarColor(client),avatar=client.logo?`<span class="client-option-avatar client-logo-avatar"><img src="${esc(client.logo)}" alt=""></span>`:`<span class="client-option-avatar" style="background:${esc(color)};color:${clientAvatarText(color)}">${esc(initials(client.name||'K'))}</span>`;return`<button class="client-option invoice-client-option" onclick="selectOfferClient(${index})">${avatar}<strong>${esc(client.name||'Bez naziva')}</strong><span>${esc(client.email||client.phone||'—')}</span><span>${esc([client.city,client.country].filter(Boolean).join(', ')||'—')}</span></button>`}).join('')}`:'<div class="empty" style="padding:24px 12px">Nema klijenata.</div>'}
selectOfferClient=function(index){const client=getClients()[index];if(!client)return;Object.assign(offerState,{clientName:client.name||'',clientAddress:client.address||'',clientCity:client.city||'',clientCountry:client.country||'',clientEmail:client.email||''});[['ofClient','clientName'],['ofAddress','clientAddress'],['ofCity','clientCity'],['ofCountry','clientCountry'],['ofEmail','clientEmail']].forEach(([id,key])=>{if($(id))$(id).value=offerState[key]});$('offerClientPicker')?.classList.remove('placeholder');if($('offerClientPicker'))$('offerClientPicker').innerHTML=`<span>${esc(client.name||'Bez naziva')}</span>`;if($('offerClientDropdown'))$('offerClientDropdown').style.display='none';updateOfferPreview()};
function clearOfferClient(){Object.assign(offerState,{clientName:'',clientAddress:'',clientCity:'',clientCountry:'',clientEmail:''});['ofClient','ofAddress','ofCity','ofCountry','ofEmail'].forEach(id=>{if($(id))$(id).value=''});if($('offerClientPicker')){$('offerClientPicker').className='client-picker-box placeholder';$('offerClientPicker').innerHTML='<span>Odaberi sačuvanog klijenta...</span>'}updateOfferPreview()}

convertOfferToInvoice=function(id){const offer=getOffers().find(item=>String(item.id)===String(id));if(!offer)return;saveDraft({number:nextInvoiceNumber(),issueDate:today(),dueDate:addDays(today(),getSettings().dueDays),status:'draft',currency:offer.currency,paymentMethod:getSettings().paymentMethod,clientName:offer.clientName,clientAddress:offer.clientAddress,clientCity:offer.clientCity,clientCountry:offer.clientCountry||'',clientEmail:offer.clientEmail,clientIdNo:'',clientVat:'',globalDiscountType:'percent',globalDiscount:0,items:JSON.parse(JSON.stringify(offer.items||[])),note:offer.note,sourceOfferId:offer.id});navigate('invoice');toast('Ponuda je pretvorena u novi nacrt fakture.')};
const saveInvoiceRecordBeforeOfferCleanup=saveInvoiceRecord;
saveInvoiceRecord=function(){const sourceOfferId=invoiceState?.sourceOfferId,result=saveInvoiceRecordBeforeOfferCleanup();if(result&&sourceOfferId!==undefined&&sourceOfferId!==null){saveOffers(getOffers().filter(offer=>String(offer.id)!==String(sourceOfferId)));toast('Faktura je sačuvana, a izvorna ponuda uklonjena.')}return result};

function openNotificationItem(id){const invoice=getInvoices().find(item=>String(item.id)===String(id));closeNotifications();if(!invoice){toast('Povezana faktura više nije dostupna.');return}editInvoice(invoice.id)}
openNotifications=function(){const host=$('notificationPopover');if(!host)return;if(host.innerHTML){closeNotifications();return}const items=getNotifications?.()||[];host.innerHTML=`<div class="notification-popover"><div class="notification-popover-head"><strong>Obavijesti</strong><button class="btn light tiny" onclick="clearNotifications()">Očisti obavijesti</button></div>${items.length?items.map(item=>`<button class="notification-row" onclick='openNotificationItem(${JSON.stringify(String(item.id))})'><strong>${esc(item.title)}</strong><small>${esc(item.detail)}</small></button>`).join(''):'<div class="empty">Nema novih obavijesti.</div>'}</div>`};

function findExactSearchRow(type,id){const rows=[...document.querySelectorAll('#viewContainer table tbody tr')];if(type==='invoice'){const item=getInvoices().find(row=>String(row.id)===String(id));return rows.find(row=>row.querySelector('td:first-child strong')?.textContent.trim()===String(item?.number||''))}if(type==='offer'){const item=getOffers().find(row=>String(row.id)===String(id));return rows.find(row=>row.querySelector('td:first-child strong')?.textContent.trim()===String(item?.number||''))}if(type==='client')return rows.find(row=>row.querySelector('.client-cell strong,td:first-child strong')?.textContent.trim()===String(id));if(type==='catalog'){const item=getCatalog().find(row=>String(row.code||row.name)===String(id));return rows.find(row=>row.textContent.includes(item?.name||'\u0000'))}return null}
function pulseExactSearchRow(type,id){setTimeout(()=>{const target=findExactSearchRow(type,id);if(!target){toast('Rezultat je pronađen, ali nije vidljiv u trenutnom filteru.');return}target.scrollIntoView({behavior:'smooth',block:'center'});target.classList.remove('search-target-pulse');void target.offsetWidth;target.classList.add('search-target-pulse');setTimeout(()=>target.classList.remove('search-target-pulse'),1800)},100)}
openTopSearchResult=function(type,id){const query=$('globalSearch')?.value||$('topSearchInput')?.value||'';closeTopbarSearch();if($('globalSearch'))$('globalSearch').value='';if(type==='page'){navigate(id);return}const route=type==='invoice'?'invoices':type==='client'?'clients':type==='offer'?'offers':'catalog';navigate(route);setTimeout(()=>{if(type==='invoice'){clearInvoiceFilters?.();setInvoiceFilter?.('q',query)}const filter=$(type==='invoice'?'icSearch':type==='client'?'clientFilter':type==='offer'?'offerFilter':'catalogSearch');if(filter&&type!=='invoice'){filter.value=query;filter.dispatchEvent(new Event('input',{bubbles:true}))}pulseExactSearchRow(type,id)},0)};

saveInvoiceStatus=function(id,status){if(status==='partial'){refreshCurrentView();setTimeout(()=>{recordPaymentModal(id);if($('payAmount')){$('payAmount').value='';$('payAmount').focus()}},0);return}const invoices=getInvoices(),index=invoices.findIndex(item=>String(item.id)===String(id));if(index<0)return;const invoice=invoices[index];if(status==='paid')invoice.paidAmount=+invoice.total||0;else invoice.paidAmount=0;invoice.status=status;invoices[index]=invoice;if(!saveInvoices(invoices))return;updateInvoiceBadge();toast(status==='paid'?'Faktura je označena kao plaćena.':status==='sent'?'Faktura je označena kao poslana.':'Status fakture je promijenjen.');refreshCurrentView()};
const savePaymentBeforePartialStatus=savePayment;
savePayment=function(id){savePaymentBeforePartialStatus(id);const invoices=getInvoices(),index=invoices.findIndex(item=>String(item.id)===String(id));if(index<0)return;const invoice=invoices[index];if((+invoice.paidAmount||0)>0&&(+invoice.paidAmount||0)<(+invoice.total||0)&&invoice.status!=='partial'){invoice.status='partial';saveInvoices(invoices);refreshCurrentView()}};

const renderCalendarWithEventClasses=renderCalendarFull;
renderCalendarFull=function(){renderCalendarWithEventClasses();document.querySelectorAll('.calendar-event-button').forEach(button=>{const type=[...button.querySelector('.calendar-dot')?.classList||[]].find(value=>value!=='calendar-dot');if(type)button.classList.add(`event-${type}`)})};routes.calendar=renderCalendarFull;
